<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
$db=saas_db();
$ticketNo=trim((string)($_GET['ticket']??''));
if($ticketNo===''){http_response_code(400);exit('Ticket number is required.');}
$q=$db->prepare("SELECT ti.id,ti.ticket_number,ti.status,ti.issued_at,ti.voided_at,pp.full_name,pp.phone,t.name tour_name,t.start_date,t.end_date,o.name organization_name FROM ticket_instances ti JOIN tour_passengers tp ON tp.id=ti.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=ti.tour_id JOIN organizations o ON o.id=ti.organization_id WHERE ti.ticket_number=? LIMIT 1");$q->execute([$ticketNo]);$ticket=$q->fetch();
$valid=$ticket&&$ticket['status']==='ISSUED'&&$ticket['voided_at']===null&&$ticket['status']!=='VOID';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket Verification</title><style>body{margin:0;background:#f4f7fb;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:650px;margin:45px auto;padding:0 16px}.card{background:#fff;border-radius:18px;padding:28px;box-shadow:0 8px 30px #0000000b}.status{font-size:18px;font-weight:800;padding:14px;border-radius:12px;margin-bottom:20px;background:<?=($valid?'#ecfdf3':'#fef3f2')?>;color:<?=($valid?'#067647':'#b42318')?>}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.item{padding:12px;background:#f8fafc;border-radius:10px}.label{font-size:12px;color:#667085}.value{font-weight:700;margin-top:3px}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="card"><h1>Ticket Verification</h1><?php if(!$ticket):?><div class="status">INVALID — Ticket not found.</div><p>Please check the ticket number.</p><?php else:?><div class="status"><?=($valid?'VALID TICKET':'VOID / INVALID TICKET')?></div><div class="grid"><div class="item"><div class="label">Ticket</div><div class="value"><?=saas_h($ticket['ticket_number'])?></div></div><div class="item"><div class="label">Passenger</div><div class="value"><?=saas_h($ticket['full_name'])?></div></div><div class="item"><div class="label">Tour</div><div class="value"><?=saas_h($ticket['tour_name'])?></div></div><div class="item"><div class="label">Organization</div><div class="value"><?=saas_h($ticket['organization_name'])?></div></div><div class="item"><div class="label">Phone</div><div class="value"><?=saas_h($ticket['phone']??'')?></div></div><div class="item"><div class="label">Issued</div><div class="value"><?=saas_h($ticket['issued_at'])?></div></div></div><?php endif;?></div></main></body></html>